dslRule:
/*!id: simplify-iparent-module-check*/
/*!description: Remove explicit exclusion of IModuleDescription from IParent checks, as module support has evolved.*/
/*!severity: HINT*/

$var instanceof org.eclipse.jdt.core.IParent && !($var instanceof org.eclipse.jdt.core.IModuleDescription)
=>
$var instanceof org.eclipse.jdt.core.IParent
;;

beforeExample:
package test;

import org.eclipse.jdt.core.IParent;
import org.eclipse.jdt.core.IModuleDescription;

public class TestClass {
    public void checkParent(Object element) {
        // Rule match 1
        if (element instanceof IParent && !(element instanceof IModuleDescription)) {
            System.out.println("Valid IParent, not IModuleDescription");
        }
        // Rule match 2 (if part of a larger condition)
        boolean condition = true;
        if (condition && element instanceof IParent && !(element instanceof IModuleDescription)) {
            System.out.println("Combined condition");
        }
    }
}

afterExample:
