import org.eclipse.jdt.core.IParent;
import org.eclipse.jdt.core.IModuleDescription;

public class TestClass {
    public void checkParent(Object element) {
        // Rule match 1
        if (element instanceof IParent) {
            System.out.println("Valid IParent, not IModuleDescription");
        }
        // Rule match 2 (if part of a larger condition)
        boolean condition = true;
        if (condition && element instanceof IParent) {
            System.out.println("Combined condition");
        }
    }
}

negativeExample:
package test;

import org.eclipse.jdt.core.IParent;
import org.eclipse.jdt.core.IType;
import org.eclipse.jdt.core.IModuleDescription;

public class TestClass {
    public void checkOther(Object element) {
        // This should not be affected, as it's not IModuleDescription
        if (element instanceof IParent && !(element instanceof IType)) {
            System.out.println("Valid IParent, not IType");
        }
        // This should not be affected as it's not the specific exclusion pattern
        if (!(element instanceof IParent)) {
            System.out.println("Not an IParent");
        }
        // This should not be affected, different type check
        if (element instanceof String && !(element instanceof Integer)) {
            System.out.println("String but not Integer");
        }
        // This should not be affected, as it's only IModuleDescription check
        if (element instanceof IModuleDescription) {
            System.out.println("Just IModuleDescription");
        }
    }
}
